let count = 0;

async function init() {
  const saved = await __amiba__.storage.get('counter_value');
  if (saved !== undefined && saved !== null) count = saved;
  updateDisplay();
}

function updateDisplay() {
  const el = document.getElementById('count_text');
  if (el) el.textContent = String(count);
}

async function handlePlus() {
  count++;
  await __amiba__.storage.set('counter_value', count);
  updateDisplay();
}

async function handleMinus() {
  count--;
  await __amiba__.storage.set('counter_value', count);
  updateDisplay();
}

async function handleReset() {
  count = 0;
  await __amiba__.storage.set('counter_value', count);
  updateDisplay();
  __amiba__.showToast('已重置', 'success');
}

init();
